import type { Request, Response } from 'express';

export type ProductCategory = 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

export interface Product {
  id: string;
  name: string;
  category: ProductCategory;
  price: number;
  description: string;
  imageUrl: string;
  featured: boolean;
}

const products: Product[] = [
  // Pottery
  {
    id: 'pot-001',
    name: 'Earthy Stoneware Bowl',
    category: 'pottery',
    price: 48.0,
    description: 'Hand-thrown stoneware bowl with a warm terracotta glaze. Perfect for everyday use or as a centerpiece.',
    imageUrl: '/airo-assets/images/products/pottery-bowl',
    featured: true,
  },
  {
    id: 'pot-002',
    name: 'Rustic Ceramic Vase',
    category: 'pottery',
    price: 72.0,
    description: 'A tall, elegant vase with a matte earth-tone finish. Each piece is uniquely shaped by hand.',
    imageUrl: '/airo-assets/images/products/pottery-vase',
    featured: false,
  },
  {
    id: 'pot-003',
    name: 'Speckled Mug Set',
    category: 'pottery',
    price: 56.0,
    description: 'Set of two hand-thrown mugs with a speckled glaze in warm cream and brown tones.',
    imageUrl: '/airo-assets/images/products/pottery-bowl',
    featured: false,
  },
  // Textiles
  {
    id: 'tex-001',
    name: 'Woven Linen Throw',
    category: 'textiles',
    price: 95.0,
    description: 'Handwoven on a traditional loom using natural linen. Soft, breathable, and beautifully textured.',
    imageUrl: '/airo-assets/images/products/textile-throw',
    featured: true,
  },
  {
    id: 'tex-002',
    name: 'Indigo Table Runner',
    category: 'textiles',
    price: 42.0,
    description: 'Hand-dyed indigo table runner with a subtle stripe pattern. Adds warmth to any dining table.',
    imageUrl: '/airo-assets/images/products/textile-weave',
    featured: false,
  },
  {
    id: 'tex-003',
    name: 'Wool Wall Hanging',
    category: 'textiles',
    price: 128.0,
    description: 'A statement wall hanging woven from undyed natural wool. Brings texture and warmth to any room.',
    imageUrl: '/airo-assets/images/products/textile-weave',
    featured: false,
  },
  // Woodwork
  {
    id: 'wood-001',
    name: 'Turned Walnut Bowl',
    category: 'woodwork',
    price: 115.0,
    description: 'Hand-turned from a single piece of walnut. The natural grain makes every bowl one of a kind.',
    imageUrl: '/airo-assets/images/products/woodwork-bowl',
    featured: true,
  },
  {
    id: 'wood-002',
    name: 'Floating Wall Shelf',
    category: 'woodwork',
    price: 88.0,
    description: 'Solid oak floating shelf with a natural oil finish. Minimal hardware, maximum character.',
    imageUrl: '/airo-assets/images/products/woodwork-shelf',
    featured: false,
  },
  {
    id: 'wood-003',
    name: 'Carved Serving Board',
    category: 'woodwork',
    price: 64.0,
    description: 'Hand-carved charcuterie board from reclaimed maple. A beautiful addition to any kitchen.',
    imageUrl: '/airo-assets/images/products/woodwork-bowl',
    featured: false,
  },
  // Jewelry
  {
    id: 'jew-001',
    name: 'Hammered Silver Pendant',
    category: 'jewelry',
    price: 78.0,
    description: 'Sterling silver pendant with a hand-hammered texture. Hung on a delicate 18" chain.',
    imageUrl: '/airo-assets/images/products/jewelry-pendant',
    featured: true,
  },
  {
    id: 'jew-002',
    name: 'Stacking Ring Set',
    category: 'jewelry',
    price: 52.0,
    description: 'Set of three hand-forged stacking rings in mixed metals. Wear together or separately.',
    imageUrl: '/airo-assets/images/products/jewelry-ring',
    featured: false,
  },
  {
    id: 'jew-003',
    name: 'Copper Leaf Earrings',
    category: 'jewelry',
    price: 38.0,
    description: 'Lightweight copper earrings shaped like leaves. Hand-cut and polished to a warm shine.',
    imageUrl: '/airo-assets/images/products/jewelry-pendant',
    featured: false,
  },
];

export default function handler(req: Request, res: Response) {
  const { category, featured } = req.query;

  let filtered = [...products];

  if (category && typeof category === 'string') {
    filtered = filtered.filter((p) => p.category === category);
  }

  if (featured === 'true') {
    filtered = filtered.filter((p) => p.featured);
  }

  res.json({ products: filtered });
}

import { useState, useEffect } from 'react';
import { Link, NavLink } from 'react-router-dom';
import { Menu, X } from 'lucide-react';

const navLinks = [
  { label: 'Home', to: '/' },
  { label: 'Products', to: '/products' },
  { label: 'About', to: '/about' },
];

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? 'bg-[#FAF7F2]/95 backdrop-blur-md shadow-sm'
          : 'bg-[#FAF7F2]'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 lg:px-8">
        <div className="flex items-center justify-between h-20 md:h-24">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Artisan Goods Co."
              className="h-10 md:h-12 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map(({ label, to }) => (
              <NavLink
                key={to}
                to={to}
                end={to === '/'}
                className={({ isActive }) =>
                  `relative text-sm font-medium tracking-wide transition-colors duration-200 group ${
                    isActive
                      ? 'text-primary'
                      : 'text-[#3D2B1F] hover:text-primary'
                  }`
                }
              >
                {({ isActive }) => (
                  <>
                    {label}
                    <span
                      className={`absolute -bottom-1 left-0 h-0.5 bg-primary transition-all duration-300 ${
                        isActive ? 'w-full' : 'w-0 group-hover:w-full'
                      }`}
                    />
                  </>
                )}
              </NavLink>
            ))}
            <Link
              to="/products"
              className="ml-2 px-5 py-2.5 bg-primary text-white text-sm font-medium rounded-sm hover:bg-primary/90 transition-colors duration-200"
            >
              Shop Now
            </Link>
          </nav>

          {/* Mobile Menu Button */}
          <button
            className="md:hidden p-2 text-[#3D2B1F] hover:text-primary transition-colors"
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label={menuOpen ? 'Close menu' : 'Open menu'}
          >
            {menuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
